import numpy as np

def priority_v2(SH, EMP, AVG, CUR, RI, DIFF):
    epsilon = 1e-9  # Avoid division by zero

    # Compute normalized available space (logarithmic entropy-like effect)
    try:
        entropy = -np.log(EMP / (SH + epsilon) + epsilon)
    except:
        entropy = np.inf

    # Compute blocking variance
    if SH == 0:
        var_block = 0
    else:
        var_block = np.var([1 if i < CUR else 0 for i in range(1, SH + 1)]) * (RI + 1)

    # Compute alignment score based on DIFF
    if DIFF <= 0:
        align_score = 0
    else:
        align_score = 1 / (np.sqrt(DIFF) + 1)

    # Hybrid priority calculation
    priority = (entropy * (SH + 1)) + (var_block * (EMP + 1)) - align_score

    return priority
